#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int dat = 0, loi = 0, chua = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 1) dat++;
        else if (x == 0) loi++;
        else chua++;
    }
    int tile = ((dat + loi) * 100) / n;
    printf("%d %d %d %d\n", dat, loi, chua, tile);
    return 0;
}
